require_once __DIR__.'/../../includes/cors.php';require_once __DIR__.'/../../includes/response.php';require_once __DIR__.'/../../includes/helpers.php';require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../includes/admin-audit.php';
if($_SERVER['REQUEST_METHOD']!=='POST')json_response(['success'=>false,'message'=>'Method not allowed'],405);$user=require_auth($pdo);require_role($user,['super_admin']);$in=get_json_input();$id=(int)($in['subscription_id']??0);$status=(string)($in['status']??'');if(!$id||!in_array($status,['trial','active','past_due','expired','cancelled','suspended'],true))json_response(['success'=>false,'message'=>'Invalid status data'],422);
try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT tenant_id,plan_id,status FROM tenant_subscriptions WHERE id=:id FOR UPDATE');$q->execute([':id'=>$id]);$old=$q->fetch();if(!$old)throw new RuntimeException('Subscription not found');$pdo->prepare('UPDATE tenant_subscriptions SET status=:s,updated_at=NOW() WHERE id=:id')->execute([':s'=>$status,':id'=>$id]);admin_audit_log($pdo,$user,'subscription.status_changed','subscription',$id,'Subscription status changed',['status'=>$old['status']],['status'=>$status],['tenant_id'=>$old['tenant_id'],'plan_id'=>$old['plan_id']]);$pdo->commit();json_response(['success'=>true,'message'=>'Subscription status updated']);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();json_response(['success'=>false,'message'=>$e->getMessage()],422);}

